package org.json;import java.util.*;public class JSONObject{public static final Object NULL=new Object();final Map<String,Object> map;JSONObject(Map<String,Object> m){map=m;}public JSONObject(String s)throws JSONException{map=((JSONObject)new JSON(s).value()).map;}public Object get(String k)throws JSONException{if(!map.containsKey(k))throw new JSONException(k);return map.get(k);}public Object opt(String k){return map.get(k);}public boolean has(String k){return map.containsKey(k);}public int getInt(String k)throws JSONException{return ((Number)get(k)).intValue();}public String getString(String k)throws JSONException{return (String)get(k);}public JSONObject getJSONObject(String k)throws JSONException{return (JSONObject)get(k);}public JSONObject optJSONObject(String k){Object o=opt(k);return o instanceof JSONObject?(JSONObject)o:null;}public JSONArray getJSONArray(String k)throws JSONException{return (JSONArray)get(k);}public JSONArray optJSONArray(String k){Object o=opt(k);return o instanceof JSONArray?(JSONArray)o:null;}public String optString(String k,String d){Object o=opt(k);return o instanceof String?(String)o:d;}public Iterator<String> keys(){return map.keySet().iterator();}}